import{_ as s,o as t,c as o,ag as a}from"./chunks/framework.NkeMC67b.js";const h=JSON.parse('{"title":"Enrollment & access","description":"Configure who can enroll in a Sikshya course, how lessons unlock, and what guests vs members can see — including drip, prerequisites, and bundles.","frontmatter":{"title":"Enrollment & access","description":"Configure who can enroll in a Sikshya course, how lessons unlock, and what guests vs members can see — including drip, prerequisites, and bundles."},"headers":[],"relativePath":"enrollment-settings.md","filePath":"enrollment-settings.md","lastUpdated":1778327862000}'),r={name:"enrollment-settings.md"};function n(l,e,i,c,u,p){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="enrollment-access" tabindex="-1">Enrollment &amp; access <a class="header-anchor" href="#enrollment-access" aria-label="Permalink to &quot;Enrollment &amp; access&quot;">​</a></h1><p>This page covers every way a learner gets <strong>into</strong> a course, and every way you control what they see <strong>after</strong> they&#39;re in.</p><h2 id="the-four-ways-to-enroll" tabindex="-1">The four ways to enroll <a class="header-anchor" href="#the-four-ways-to-enroll" aria-label="Permalink to &quot;The four ways to enroll&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>When</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Free</strong></td><td>The course price is <code>0</code></td><td>Learner clicks <strong>Enroll</strong> → instantly enrolled.</td></tr><tr><td><strong>Paid</strong></td><td>The course has a price</td><td>Learner buys at checkout (PayPal, etc.). On success → enrolled.</td></tr><tr><td><strong>Manual</strong></td><td>Anything bespoke — gifts, B2B, refund recovery</td><td>Admin enrolls the user from <span class="screen-path">People → Enrollments</span>.</td></tr><tr><td><strong>Coupon</strong></td><td>Promotions or partial discount</td><td>Admin issues a coupon. Learner applies it at checkout.</td></tr></tbody></table><p>All four routes write the same enrollment record and trigger the same email + downstream automation.</p><h2 id="settings-→-enrollment" tabindex="-1">Settings → Enrollment <a class="header-anchor" href="#settings-→-enrollment" aria-label="Permalink to &quot;Settings → Enrollment&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → Settings → Enrollment</span>. Sections:</p><h3 id="purchase-enrollment" tabindex="-1">Purchase &amp; enrollment <a class="header-anchor" href="#purchase-enrollment" aria-label="Permalink to &quot;Purchase &amp; enrollment&quot;">​</a></h3><ul><li><strong>Auto-enroll on purchase</strong> — leave on. When a learner pays, they&#39;re enrolled automatically.</li><li><strong>Button text on paid courses</strong> — what the catalog button says (default: &quot;Buy now&quot;).</li><li><strong>Button text on free courses</strong> — default: &quot;Enroll now&quot;.</li><li><strong>Let administrators enroll without purchase</strong> — leave on so manual enroll works.</li><li><strong>Enable guest checkout</strong> — let buyers pay without creating an account first. We auto-create the account on success.</li></ul><h3 id="dynamic-checkout-fields-pro" tabindex="-1">Dynamic checkout fields <span class="pro-pill">PRO</span> <a class="header-anchor" href="#dynamic-checkout-fields-pro" aria-label="Permalink to &quot;Dynamic checkout fields &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h3><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Custom checkout questions</span></div><p class="pro-callout__desc">Add VAT IDs, referral source, consent checkboxes, or T-shirt size to checkout. Every field can be text, select, or checkbox — with simple visibility rules (show this field only when the buyer picks &quot;Other&quot;). Answers are stored on the order and the learner profile.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock dynamic fields →</a></div><h3 id="course-completion" tabindex="-1">Course completion <a class="header-anchor" href="#course-completion" aria-label="Permalink to &quot;Course completion&quot;">​</a></h3><ul><li><strong>When is a course complete?</strong> — pick the rule (All lessons done / All lessons + quizzes + assignments / Pass all quizzes / Manual mark).</li><li><strong>Minimum progress %</strong> — issue completion at e.g. 95% so a single forgotten lesson doesn&#39;t block the cert.</li></ul><h3 id="enrollment-limits" tabindex="-1">Enrollment limits <a class="header-anchor" href="#enrollment-limits" aria-label="Permalink to &quot;Enrollment limits&quot;">​</a></h3><ul><li><strong>Max learners per course</strong> — optional cap.</li><li><strong>Access length after enroll (days)</strong> — useful for time-limited courses. Empty = forever.</li><li><strong>Max active courses per student</strong> — if you want to throttle free users.</li></ul><h3 id="unenrollment" tabindex="-1">Unenrollment <a class="header-anchor" href="#unenrollment" aria-label="Permalink to &quot;Unenrollment&quot;">​</a></h3><ul><li><strong>Let students leave</strong> — give learners a self-unenroll button on their account.</li><li><strong>Try to refund automatically when a student leaves</strong> — best-effort, depends on the gateway. We recommend processing refunds in your gateway dashboard for safety.</li><li><strong>Days after signup they can still drop</strong> — refund-window logic.</li></ul><h3 id="enrollment-periods" tabindex="-1">Enrollment periods <a class="header-anchor" href="#enrollment-periods" aria-label="Permalink to &quot;Enrollment periods&quot;">​</a></h3><ul><li><strong>Limit enrollment to date ranges</strong> — for cohorts.</li><li><strong>Default enrollment opens / closes</strong> — site-wide default. Per-course overrides live in the Course Builder → Pricing &amp; access tab.</li></ul><h2 id="sequential-progression-free" tabindex="-1">Sequential progression (free) <a class="header-anchor" href="#sequential-progression-free" aria-label="Permalink to &quot;Sequential progression (free)&quot;">​</a></h2><p>This is the free plugin&#39;s &quot;drip light&quot;. With it on, learners must complete each lesson in order before the next unlocks.</p><p>Toggle per-course in the Course Builder → <strong>Course options</strong> → <strong>Track student progress</strong>. With the option on, the learn hub locks future lessons until earlier ones are marked complete.</p><h2 id="drip-—-release-lessons-by-schedule-pro" tabindex="-1">Drip — release lessons by schedule <span class="pro-pill">PRO</span> <a class="header-anchor" href="#drip-—-release-lessons-by-schedule-pro" aria-label="Permalink to &quot;Drip — release lessons by schedule &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Content drip — date / X-days / cohort schedules</span></div><p class="pro-callout__desc">Want lessons to release &quot;on March 15&quot;, &quot;7 days after each learner enrolls&quot;, or &quot;on day 14 of cohort A&quot;? That&#39;s <strong>Content drip</strong>. Visit <span class="screen-path">Sikshya → Course → Learning rules → Scheduled access</span> after enabling the add-on.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock content drip →</a></div><p>Drip rules live on a dedicated screen. Each rule specifies:</p><ul><li><strong>Course</strong> — which course it applies to.</li><li><strong>Mode</strong> — Date, X days from enrollment, Cohort start, or After lesson.</li><li><strong>Schedule</strong> — date / day count / cohort id.</li><li><strong>Targets</strong> — which lessons to unlock (all lessons in chapter X, specific lessons, etc.).</li></ul><p>Combine drip with <strong>Drip notifications</strong> <span class="pro-pill">PRO</span> for &quot;your next lesson is now available&quot; emails.</p><h2 id="prerequisites-pro" tabindex="-1">Prerequisites <span class="pro-pill">PRO</span> <a class="header-anchor" href="#prerequisites-pro" aria-label="Permalink to &quot;Prerequisites &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Require courses or lessons before unlocking the next</span></div><p class="pro-callout__desc">Lock <strong>Course B</strong> until the learner has finished <strong>Course A</strong>. Or lock the &quot;Final exam&quot; lesson until the prep lessons are complete. Friendly &quot;what to do next&quot; messaging is built in.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock prerequisites →</a></div><p>Find prerequisites under <span class="screen-path">Sikshya → Course → Learning rules → Prerequisites</span> after enabling the add-on, or set per-course in the Course Builder → <strong>Pricing &amp; access</strong> tab.</p><h2 id="coupons-free" tabindex="-1">Coupons (free) <a class="header-anchor" href="#coupons-free" aria-label="Permalink to &quot;Coupons (free)&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → Commerce → Coupons</span>. Click <strong>+ New coupon</strong>.</p><p>Fields:</p><ul><li><strong>Coupon code</strong> — what learners type at checkout.</li><li><strong>Type</strong> — Percentage off or Fixed amount off.</li><li><strong>Amount</strong> — <code>25</code> for 25% off (percentage) or <code>25</code> for $25 off (fixed).</li><li><strong>Minimum order</strong> — skip if you don&#39;t want a floor.</li><li><strong>Usage limit (total)</strong> — total times the coupon can be redeemed.</li><li><strong>Usage limit per customer</strong> — per-learner cap (typically 1).</li><li><strong>Valid from / Valid until</strong> — optional date window.</li><li><strong>Applies to</strong> — All courses, or specific courses (multi-select).</li></ul><p>Click <strong>Save</strong>. Test the coupon at checkout in a private window before sharing it.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced coupons</span></div><p class="pro-callout__desc">Add minimum cart total, course / category exclusions, &quot;first-time buyer only&quot; rules, and stacking guards (allow / deny combining coupons).</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock advanced coupons →</a></div><h2 id="bundles-subscriptions-pro" tabindex="-1">Bundles &amp; subscriptions <span class="pro-pill">PRO</span> <a class="header-anchor" href="#bundles-subscriptions-pro" aria-label="Permalink to &quot;Bundles &amp; subscriptions &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Sell bundles and recurring subscriptions</span></div><p class="pro-callout__desc">Bundle several courses for one bundled price (Course Bundles add-on). Or charge monthly / yearly for member-only access (Subscriptions add-on). Both unlock new &quot;course type&quot; options in the Course Builder.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock bundles &amp; subscriptions →</a></div><p>Bundles live under <span class="screen-path">Sikshya → Commerce → Bundles</span> and have their own builder. Subscriptions add a <strong>Subscriptions</strong> menu and a <strong>Plans</strong> sub-screen for monthly / yearly tier configuration.</p><h2 id="marketplace-pro" tabindex="-1">Marketplace <span class="pro-pill">PRO</span> <a class="header-anchor" href="#marketplace-pro" aria-label="Permalink to &quot;Marketplace &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Multi-vendor marketplace</span></div><p class="pro-callout__desc">Open the academy to many independent sellers (vendors). Each vendor has their own storefront. Set per-vendor / per-course commission, manage payouts, and report on GMV.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock the marketplace →</a></div><p>Find it under <span class="screen-path">Sikshya → Commerce → Marketplace</span> after the <strong>Marketplace multi-vendor</strong> add-on is on.</p><h2 id="refunds-unenroll" tabindex="-1">Refunds &amp; unenroll <a class="header-anchor" href="#refunds-unenroll" aria-label="Permalink to &quot;Refunds &amp; unenroll&quot;">​</a></h2><p>You can revoke an enrollment two ways:</p><ul><li><strong>From Enrollments</strong> → tick the row → bulk action <strong>Cancel enrollment</strong>.</li><li><strong>From the order</strong> → open <span class="screen-path">Commerce → Sales → Orders</span> → click the order → <strong>Refund</strong>.</li></ul><p>Refunding marks the enrollment <strong>Refunded</strong> and writes a refund row. If you set &quot;Try to refund automatically&quot; in Settings → Enrollment, Sikshya attempts the API call to your gateway. <strong>For safety</strong>, refund first in the gateway dashboard, then mark refunded in Sikshya.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/plugins/sikshya/payment-settings">Payments</a> — gateway-by-gateway setup.</li><li><a href="/plugins/sikshya/email-settings">Email &amp; notifications</a> — the messages that fire on enrollment.</li><li><a href="/plugins/sikshya/third-party-integrations">Pro add-ons</a> — every Pro feature listed.</li></ul>',48)])])}const g=s(r,[["render",n]]);export{h as __pageData,g as default};
